urlset:


  {{ site_url }}/
  daily
  1.0



{% for cat in categories %}

  {{ site_url }}/category/{{ cat | urlencode }}
  daily
  0.8

{% endfor %}


{% for article in articles %}

  {{ site_url }}/article/{{ article.slug }}
  {{ (article.updated_at or article.published_at) | format_iso }}
  monthly
  0.7

{% endfor %}
